sys_script_vtable.script:
(function executeQuery(v_table, v_query) {
    var encodedQuery = v_query.getEncodedQuery();
    var siteSysID = '';
    var hostCircuitSysID = '';
    var localCircuitSysID = '';

    if (!gs.nil(encodedQuery)) {
        var filterObj = _decodeQueryFilter(encodedQuery);
        siteSysID = filterObj.site;
        hostCircuitSysID = filterObj.pe_host_circuit_id;
        localCircuitSysID = filterObj.local_circuit_id;
        // Do not load data if siteSysID is not present
        if (siteSysID) {
            _loadData(siteSysID, hostCircuitSysID,localCircuitSysID);
        }
    }

    function _decodeQueryFilter(encodedFilter) {
        var filterParts = encodedQuery.split("^");
        var result = {
            site: '',
            pe_host_circuit_id: '',
            local_circuit_id: ''
        };

        filterParts.forEach(function(filter) {
            if (_filterContains(filter, "javascript:")) {
                var evaluator = new GlideEvaluator();
                var jsResult = evaluator.evaluateString(filter.split('javascript:')[1]);
                filter = filter.replace(/javascript:.*/i, jsResult);
            }
            if (_filterContains(filter, "site=")) {
                result.site = filter.split('=')[1];
            } else if (_filterContains(filter, "pe_host_circuit_id=")) {
                result.pe_host_circuit_id = filter.split('=')[1];
            }  else if (_filterContains(filter, "local_circuit_id=")) {
                result.local_circuit_id = filter.split('=')[1];
            }
        });

        return result;
    }

    function _filterContains(filter, element) {
        return filter.indexOf(element) >= 0;
    }

    function _loadData(site,hostCircuitSysID, localCircuitSysID){
		var port = new x_g_sonc_ns_pro.port();

		var portObj = port.loadProposedPortTable(site,hostCircuitSysID, localCircuitSysID);

		for(var row in portObj){
			v_table.addRow(portObj[row]);
		}

    }


})(v_table, v_query);
